INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تعلّمي كيف تحسب كمية بذور الشوفان لكل هكتار بأدق طرق لتحسين الإنتاجية، مع استرشافات شاملا حول أفضل التقنيات والزراعة والري في العراق. معلومات عملية دقيقة للمزارعين.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
