INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: муҳимии парвариши системаи навори чашкӣ (тип) боғи хушкӯб</h2>\n<p>Хурак ва об ду сутуни асосии ҳосилбарории хушкӯб мебошанд, ки сифат ва ҳаҷми ҳосил дар асоси идоракунии дуруст онҳо ба таври мустақим тағйир меёбанд. <strong>Системаи навори чашкӣ (тип)</strong> Бо вуҷуди хароҷоти ибтидоии паст ва суръати баланди даркорӣ, ин система ба яке аз муҳимтарин абзорҳои ободорию дармондарии кишоварии самаранок, аз ҷумла хушкӯб табдил ёфтааст. Аммо, бисёр деҳқонон фарқияти байни «намуди дуруст» ва «парвариши асоснок»-ро муайян карда наметавонанд. Таҷриба нишон медиҳад, ки сабаби асосии кам шудани самаранокии навори чашкӣ вобаста ба вайроншавии дастгоҳ нест, балки фаромӯшӣ ё бемаърифӣ ба протоколҳои тозагӣ ва таъмири даврагӣ аст.</p>\n<p>Дар ин мустақими муфассал мо аз мавзӯҳоти умумӣ мегузарем ва бо диққат ба ҷанбаҳои техникӣ ва амалии парвариши навори чашкӣ дар боғҳои хушкӯб диққат диҳем. Мақсади мо тақдими як рамка (навост) барои деҳқон аст, то бо сармоягузории кам солҳо аз самаранокӣ системаи навори худ баръия барад ва пешгирӣ аз хароҷоти гарибе таъмири фаврӣ ва ивазкунии онро анҷом диҳад.</p>\n\n<h2>Ашноктан бо нуқтаҳои заифии системаи навори чашкӣ дар муҳити кишти хушкӯб</h2>\n<p>Ростани хушкӯб ба тағйирот (нуксетҳо) дар намнокии хок хеле ҳассос аст. Системаи навори чашкӣ бо эҷоди гилоси ободорию дармондарии дақиқ ин ниёзро иҷро мекунад; вале хусусияти аслии ин система дар афзалияти он ба зарари доридан аст. Шаҳдои ин хусусиятҳо (заифиҳо) асоси асосии барои парвариши дуруст мебошад.</p>\n<h3>Хатари аввал: баставу пур шудани канорҳои барории обро аз паҳн шудани лозимӣ ва оҳангул (осад)</h3>\n<p>Ҷамшудани намунаи капиллярӣ (тайп) яке аз мушкилоти асосӣ мебошад. Ин ҷамшудан метавонад аз се сабаби асосӣ бар ояд: химикӣ (чаниби намакҳоиminerалӣ ва моддаҳои кислота/ишқорӣи кӯдҳо), биологӣ (афзоиши ҳамаҳо ва бактерияҳо дар дохили намуна) ва физикӣ (зарраҳои муъаллақ, рӯнӣ ва сангҳои хурд). Дар киштии хияр, ки истифодаи кӯди маҳлулӣ маъмул аст, идоракунии pH-и об ва сифати кӯд нақши бевосита дорад дар кам кардани хатари химикӣ. Диди нафаси интихобӣ (фиолтратсия)-и ибтидоӣ хатари тамоми ин хатарҳоро чандбар карда мекунад.</p>\n<h3>Хатари дуюм: вайроншавии физикии бадани намуна</h3>\n<p>Бадани намунаи тайп одатан аз полиетилен фишори паст (LDPE) бо қалдобии 0.2 то 0.5 миллиметр сохта шудааст. Ин мавод ба фишори механикӣ ҳассос аст. Амалҳои киштоварӣ чунин сабуккашӣ, кӯшодани, ё ҳатто гузаштани ғайрикороти деҳқон аз рӯи намуна метавонад боиси шикастани, дараҳшудан ё пайдои вораҳои хурд шавад. Ин шикастҳо дар ибтидо маълум нестанд, боки бо идомаи обёрӣ, ҷойи дурӯи об ва решаҳои хиярро ба табоб ва ғарғарӣ мерасонад.</p>\n<h3>Хатари сеюм: вайроншавӣ аз ҷониби омили беруна</h3>\n<p>Ба иловаи омили киштоварӣ, омили муҳитӣ ҳам нақши муҳим бозидаанд. Қарор додани намуна дар даромад ба рӯшноии мустақими офтоб дар давоми вақти дароз бе муҳофизат, боиси оксидатсияи UV-и моддаи полимерӣ мешавад ва эластикӣ будани онро кам мекунад. Инчунин намуна метавонад таъсири тағйироти шидаи ҳарородро ҳисса кунад, ки метавонад боиси васеъшавӣ ва фишудани ғайритаразнан шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-خیار-با-نوار-تیپ-نکات-کلیدی-تصویر-شاخص.webp" alt="نگهداری خیار با نوار تیپ: نکات کلیدی - تصویر 1"/><figcaption>crop drip tape maintenance care хияр</figcaption></figure>\n\n\n<h2>Ихтирои пешакӣ: шустан ва тоза кардани амиқи система</h2>\n<p>Шустани муқаррарӣ, қалби задаи нигоҳдории намунаи хияр мебошад. Ин амал бояд протоколи муайян бошад, на чораи фавқулода пас аз дидашудан масъала. Ду дақиқи вақтӣ барои шустан вуҷуд дорад: ибтидоди фасл (пеш аз паҳн кардани об) ва охири фасл (пас аз тамом шудани давраи обёрӣ). Ба иловаи ин, шустаниҳои муваққати дар давоми фасл низ зарур аст.</p>\n<h3>Технология промывки под давлением</h3>\n<ol>\n<li><strong>Отключение подачи и закрытие клапанов:</strong> Систему необходимо полностью изолировать от основного источника для создания равновесного давления.</li>\n<li><strong>Подача давления с конца линии:</strong> Используя подходящий источник давления (например, насос с высоким давлением), направьте поток воды с конца линии к выпускным отверстиям. Этот поток вымывает взвешенные частицы из выпускных отверстий.</li>\n<li><strong>Продувка сжатым воздухом:</strong> После промывки водой необходимо слить воду из линии с помощью сжатого воздуха. Остаточная влага в линии создает благоприятную среду для роста плесени и водорослей во время простоя системы.</li>\n</ol>\n<h3>Дополнительные рекомендации по промывке</h3>\n<p>Дар тӯли фасл, пас аз ҳар бор партовидани моддаҳои кимиёвӣ, тавсия карда мешавад, ки широрӯро чанд дақиқа тавассути об шустан кунед, то афкандаҳои моддаи гудохта хориҷ шаванд. Истифодаи кислотаҳои заиф (мисли кислотаи ситрик ё кальсий) дар давраҳои муайян барои пешгирӣ аз афкандаҳои кимиёвӣ муфид аст, вале бояд бо эҳтиёт ва мувофиқи арзёбии истеҳсолкунанда иҷро шавад.</p>\n\n<h2>Пӯсти асборҳои ислоҳот: Ҳалли сард кардан ва иваз кардани фаврӣ</h2>\n<p>Ҳатто бо беҳтарин нигоҳдории бӯстон, пӯсидашавӣ ҳамаҷо қобили ҷойгиркунӣ нест. Дар даст доштани як пӯсти ислоҳоти оддӣ дар бӯстон, метавонад аз зарарҳои молии бузург пешгирӣ кунад.</p>\n<ul>\n<li><strong>Вобастакунандаҳои металлӣ ва пластикии:</strong> Барои пайваст кардани қисмҳои шикастони широрӯ, вобастакунандаҳои стандартӣ (Splice Connectors) истифода баред. Ин қисмҳо бояд аз маводи зич ва мутобиқ ба фишори система бошанд. Истифодаи мӯрра ё пайвастакунандаҳои ғайризарбрасонанда, ҳалли муваққат ва нопустидгор аст.</li>\n<li><strong>Нокамонии маҳаллӣ ва пӯшидан бо қап:</strong> Агар яке ё ду сӯрухи партобӣ баста бошад ва шустанаш ғайриимкон бошад, шумо метавонед сӯроҳро бо истифодаи сӯзан ё ресони кабуд кушоед. Агар мушкил ҳал наояд, сӯроҳро бо қапи пластикӣ пӯшед, то аз даҳли об ба берун барои широрӯ пешгирӣ карда шавад. Ин кор, шитоби широрӯро каме кам мекунад, вале аз ҳарофарии об пешгирӣ мекунад.</li>\n<li><strong>Капҳои ниҳоӣ (End Caps):</strong> Ҳамеша пеш аз оғози обёрӣ, пайвастагии қапҳои кунҳии навари чангӣ-печеро санҷед. Як қапи шустофт фороишро ба тамоми система бо як ҷет об берун мебарадорад ва боиси кам шудани фишор дар дигар нуқтаҳои навар мегардад.</li>\n</ul>\n<p>Барои фаҳмиши беҳтари нақши системаҳои маҷмӯӣ дар идоракунии норасонӣ, шумо метавонед бо таҳқиқоти <a href="https://navar-abyari.ir/foydahoi-nvori-tipii-obyri-tarafduzi/">фоидҳои навари чангӣ-печерии обёрӣи маҷмӯӣ</a>дониши худро дар бораи самаранокии системаҳои маҷмӯӣ тақвият диҳед.</p>\n\n<h2>Идоракунии фишор ва танзимотҳои беҳтарин барои хурма</h2>\n<p>Навари чангӣ-печерӣ дар фишорҳои хеле пасттар нисбат ба чангӣ-печерҳои сахт тарҳрезӣ шудааст. Фишори мувофиқ одатан байни 1 то 3 бар аст. Фишори зиёдтар аз 3 бар хатари партоидани бадани наварро ба таври вазъин зиёд мекунад. Фишори камтар аз 1 бар низ метавонад боиси наомади баромадани об аз сӯрохиҳои баромадгӣ бо шакли якхела гардад.</p>\n<p>Танзими фишор бояд асосан дар асоси дарозии навар, дараҷаи сарф ва намуди хок иҷро шавад. Дар хокҳои ғавғулмонда, фишори камтар ва вақти дарозтари обёрӣ тавсия мешавад. Дар хокҳои роҳӣ, фишори каме баландтар ва вақти кӯтоҳтар лозим аст. Истифодаи манометр дар оғози навар, барои назорати фишоре, ки пумп таҳвил мекунад, зарур аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-خیار-با-نوار-تیپ-نکات-کلیدی-کاربرد-عملی.webp" alt="نگهداری خیار با نوار تیپ: نکات کلیدی - تصویر 2"/><figcaption>crop drip tape maintenance care хурма</figcaption></figure>\n\n<h3>Нақши филтр дар танзими фишор</h3>\n<p>Филтр дарвозаи вориди ба система аст. Филтри пурофто фишорро ба таври ғайриоддӣ коҳиш медиҳад ва боиси хушкшавии нарм мебошад. Филтри шустанишуда тоза зарраҳои хурдро ба сӯи нарм мефиристад ва боздоширо меафзояд. Шустани филтр бояд ҳафтае як маротиба ва пас аз ҳар маротиба озуадодан иҷро шавад. Истинод аз ду филтр (филтрҳои торӣ ва филтрҳои дискӣ) дар системаҳои қабқӯл кафолати коҳиши ҷамъ овардани зарраҳои сахорон аст.</p>\n\n<h2>Барномарезии нигоҳубини фавсӣ: Ҷадвали вақтӣ амалӣ</h2>\n<p>Барномаи муайян нигоҳубини нарми қабқӯлро аз корҳои муваққатӣ ба раванди пайваста табдил медиҳад.</p>\n<table>\n  <thead>\n    <tr>\n      <th>Марҳилаҳо</th>\n      <th>Чораҳои техникикӣ</th>\n      <th>Фурғати пешниҳодшуда</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td>Оғози фавс</td>\n      <td>Санҷиди визуалии пурраи ҷисм, тоза кардани филтр, санҷиши фишори аввалин, пӯшидани охирин қисми ғӯл</td>\n      <td>Як бор</td>\n    </tr>\n    <tr>\n      <td>Ҳафтаҳои аввали карбон</td>\n      <td>Мувофиқи намунаи хушкшавии хок, танзими равшанӣ, назорати бастаҳои маҳаллӣ</td>\n      <td>Ҳар рӯз</td>\n    </tr>\n    <tr>\n      <td>Пешонаи асосии оборӣ</td>\n      <td>Санҷиши дареҳҳо, шустани филтр, шустушуви кӯтоҳи ғӯл пас аз кӯдакунӣ</td>\n      <td>Ҳар ҳафта то ду ҳафта</td>\n    </tr>\n    <tr>\n      <td>Пояи мавсим</td>\n      <td>Шустаниши амиқ, хонаи ҳаво, санҷиши дақиқ, нигоҳ доштан дар мақоми хушк ва хунук</td>\n      <td>Як маротиба</td>\n    </tr>\n  </tbody>\n</table>\n\n<h2>Саволҳои мӯрим (FAQ)</h2>\n<h3>Оё литаи тамизкунӣ (рип) дорост?</h3>\n<p>Не, литаи тамизкунии оддӣ одатан барои як маротиба аст. Гарчанде баъзе таъмирҳо болои он имконпазир аст, аммо аз ҷиҳати иқтисодӣ, иваз кардани лита дар охирҳои мавсим, ба монанди кишоварзии такрорӣ ба монанди торик, оқилона аст. Як литаи солим кафилятдиҳандаи дақиқии обёрӣ мебошад.</p>\n<h3>Беҳтарин замон барои шустаниши литаи тамизкунӣ дар кишоварзии торик чист?</h3>\n<p>Беҳтарин замон, пеш аз оғози обёрӣ дар аввали мавсим ва пеш аз бастани система дар охири мавсим аст. Илова бар ин, шустаниши кӯтоҳмуддат баъд аз ҳар як дораи ошёми кимиёвӣ тавсия мешавад.</p>\n<h3>Оё лентарои қатори (drip tape) -и харобро комилан тавба кардан мумкин аст?</h3>\n<p>Шкастҳои хурдро бо <strong>пайвасткунандаи лентаро</strong> тумор кардан мумкин аст. Аммо агар ҷисми лента дароз ва васеъи тағйирот дорад, беҳтар аст онро иваз кунед. Тумор кардани лентаҳои бешадоммазқумӣ хавфи дубора пайдо шудани низоиш ва кам шудани дақиқии обӣаро меафзояд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-خیار-با-نوار-تیپ-نکات-کلیدی-جزئیات-فنی.webp" alt="نگهداری خیار با نوار تیپ: نکات کلیدی - تصویر 3"/><figcaption>crop drip tape maintenance care хӯрмо</figcaption></figure>\n\n\n<h2>Хулоса: Сари модаи сифат</h2>\n<p>Нигаҳдорӣи лентаро дар бағори хӯрмо, таъмин намудани истифодаи об, кам кардани хароҷоти энергияи ва зиёд кардани сифат ва миқдори маҳсулоти шумост. Бо риоя намудани дастурҳои тозагӣ, диққат додан ба ситонаи мунтазам ва тумори баҳодиҳи, шумо метавонед аз шикастҳои нофаҳми ва паст шудани коркунандагии система пешгирӣ кунед.</p>\n<p>Сари модаи як <strong>Тасмаи турбиши ором</strong> Дар ҷанби барномаи мунтазами нигоҳубинӣ, калиди муваффақият дар ороёиши чӯҷукӣ каду мебошад. Ин раванд на як вазифаи техникӣ, балки як маҳорати кишоварзӣ аст, ки бояд ҷиддӣ гирифта шавад.</p>\n<p>Барои фаҳмидани беҳтари идоракунии даромад ба ҳектар дар кишти решаҳо ва сабзавот, метавонед ба мақолаи мо бо мавзӯъ <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d8%a7%d8%b3%d9%81%d9%86%d8%a7%d8%ac-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Сатҳи истеҳсоли гӯяк ба ҳектар</a> равза кунед, то диди васеътари дар бораи идоракунии замин дошта бошед.</p>\n<p><strong>Мавзӯҳои алоқаманд:</strong> <a href="https://navar-abyari.ir/%d9%85%d8%b1%d8%a7%d8%ad%d9%84-%d9%86%d8%b5%d8%a8-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be/">Марҳилаҳои насби тасмаи турби</a></p>\n<p><strong>Мавзӯҳои алоқаманд:</strong> <a href="https://navar-abyari.ir/%d8%b4%d8%b1%d9%8a%d8%b7-%d8%a7%d9%84%d8%b1%d9%8a-%d8%a8%d8%a7%d9%84%d8%aa%d9%86%d9%82%d9%8a%d8%b7-%d9%81%d9%8a-%d8%aa%da%a9%d8%b1%db%8c%d8%aa/">Рубони оборӣи тӯфонӣ дар Тикрит: ҳаллиҳои пешрафтаи кишоварзӣ барои зиёд кардани ҳосилнокӣ</a></p>','Нигораши ришаи Tuf дар парвариши хурма: Роҳнамои амиқи амалиётӣ','Шиносоии принсипҳои калидии нигоҳубини системаи капельро бағойҳои туршия. Тайёриҳои амалӣ барои пешгирии бандшавӣ, ислоҳи озодшавӣ ва зиёд кардани умри коркардси истифодаи системаи обёбӣ бо сармоягузории минималӣ.','publish','closed','closed','nigorashi-rishi-tuf-khurma',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
